/**
 * The single bidirectional session stream between a client library's admin
 * connection and the sidecar proxy. The first client message must be
 * Configure (fresh session) or Manifest (reconnect within the protection
 * window); the proxy replies Configured either way, and then dispatches
 * records.
 */
export type ProxyServiceService = typeof ProxyServiceService;
export const ProxyServiceService = {
  session: {
    path: "/parallelconsumer.proxy.v1.ProxyService/Session" as const,
    requestStream: true as const,
    responseStream: true as const,
    requestSerialize: (value: ClientMessage): Buffer => Buffer.from(ClientMessage.encode(value).finish()),
    requestDeserialize: (value: Buffer): ClientMessage => ClientMessage.decode(value),
    responseSerialize: (value: ProxyMessage): Buffer => Buffer.from(ProxyMessage.encode(value).finish()),
    responseDeserialize: (value: Buffer): ProxyMessage => ProxyMessage.decode(value),
  },
} as const;

export interface ProxyServiceServer extends UntypedServiceImplementation {
  session: handleBidiStreamingCall<ClientMessage, ProxyMessage>;
}

export interface ProxyServiceClient extends Client {
  session(): ClientDuplexStream<ClientMessage, ProxyMessage>;
  session(options: Partial<CallOptions>): ClientDuplexStream<ClientMessage, ProxyMessage>;
  session(metadata: Metadata, options?: Partial<CallOptions>): ClientDuplexStream<ClientMessage, ProxyMessage>;
}

export const ProxyServiceClient = makeGenericClientConstructor(
  ProxyServiceService,
  "parallelconsumer.proxy.v1.ProxyService",
) as unknown as {
  new (address: string, credentials: ChannelCredentials, options?: Partial<ClientOptions>): ProxyServiceClient;
  service: typeof ProxyServiceService;
  serviceName: string;
};

function bytesFromBase64(b64: string): Uint8Array {
  return Uint8Array.from(globalThis.Buffer.from(b64, "base64"));
}

function base64FromBytes(arr: Uint8Array): string {
  return globalThis.Buffer.from(arr).toString("base64");
}

type Builtin = Date | Function | Uint8Array | string | number | boolean | bigint | undefined;

export type DeepPartial<T> = T extends bigint ? string | number | bigint
  : T extends Builtin ? T : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function toTimestamp(date: Date): Timestamp {
  const seconds = BigInt(Math.trunc(date.getTime() / 1_000));
  const nanos = (date.getTime() % 1_000) * 1_000_000;
  return { seconds, nanos };
}

function fromTimestamp(t: Timestamp): Date {
  let millis = (globalThis.Number(t.seconds?.toString()) || 0) * 1_000;
  millis += (t.nanos || 0) / 1_000_000;
  return new globalThis.Date(millis);
}

function fromJsonTimestamp(o: any): Date {
  if (o instanceof globalThis.Date) {
    return o;
  } else if (typeof o === "string") {
    return new globalThis.Date(o);
  } else {
    return fromTimestamp(Timestamp.fromJSON(o));
  }
}

function isObject(value: any): boolean {
  return typeof value === "object" && value !== null;
}

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
